python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-gateway-sequence-flows/InvoiceTriageBpmn/InvoiceTriageBpmn.bpmn')
root = tree.getroot()
bpmn = 'http://www.omg.org/spec/BPMN/20100524/MODEL'
bpmndi = 'http://www.omg.org/spec/BPMN/20100524/DI'
ns = {'bpmn': bpmn, 'bpmndi': bpmndi}
proc = root.find('bpmn:process', ns)
errors = []

# 1. All IDs unique (ET guarantees parse, just check)
all_ids = {e.get('id') for e in root.iter() if e.get('id')}

# 2. sequence flow refs resolve
flows = proc.findall('bpmn:sequenceFlow', ns)
for f in flows:
    for attr in ('sourceRef','targetRef'):
        v = f.get(attr)
        if v not in all_ids:
            errors.append(f'SeqFlow {f.get(\"id\")} {attr}={v} not found')

# 3. XOR split gateways: if >1 outgoing, need default + conditions on non-defaults
for gw in proc.findall('bpmn:exclusiveGateway', ns):
    outgoing = [o.text.strip() for o in gw.findall('bpmn:outgoing', ns)]
    if len(outgoing) <= 1:
        continue  # join or pass-through — no condition rule
    default = gw.get('default')
    if not default:
        errors.append(f'XOR {gw.get(\"id\")} missing default attribute')
    for fid in outgoing:
        if fid == default:
            continue
        f = proc.find(f'bpmn:sequenceFlow[@id=\"{fid}\"]', ns)
        cond = f.find('bpmn:conditionExpression', ns) if f is not None else None
        if cond is None:
            errors.append(f'Flow {fid} from XOR {gw.get(\"id\")} missing conditionExpression')

# 4. No FAKE_JOIN: tasks/events must not have >1 incoming
task_tags = {'startEvent','endEvent','task','exclusiveGateway','parallelGateway','scriptTask','serviceTask','userTask','intermediateCatchEvent','intermediateThrowEvent'}
for e in proc.iter():
    tag = e.tag.split('}')[1] if '}' in e.tag else e.tag
    if tag in task_tags:
        incoming = [i.text.strip() for i in e.findall('{%s}incoming' % bpmn)]
        if len(incoming) > 1:
            errors.append(f'{tag} {e.get(\"id\")} has {len(incoming)} incoming flows (fake-join)')

# 5. Parallel gateways: no conditions
for gw in proc.findall('bpmn:parallelGateway', ns):
    for fid in [o.text.strip() for o in gw.findall('bpmn:outgoing', ns)]:
        f = proc.find(f'bpmn:sequenceFlow[@id=\"{fid}\"]', ns)
        cond = f.find('bpmn:conditionExpression', ns) if f is not None else None
        if cond is not None:
            errors.append(f'Parallel GW {gw.get(\"id\")} flow {fid} has unexpected condition')

# 6. Diagram: every flow node has a shape, every flow has an edge
diag = root.find('bpmndi:BPMNDiagram', ns)
plane = diag.find('bpmndi:BPMNPlane', ns)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', ns)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', ns)}
node_tags = {'startEvent','endEvent','task','exclusiveGateway','parallelGateway','scriptTask','serviceTask','userTask'}
for e in proc.iter():
    tag = e.tag.split('}')[1] if '}' in e.tag else e.tag
    eid = e.get('id')
    if tag in node_tags and eid:
        if eid not in shapes:
            errors.append(f'Missing BPMNShape for {eid}')
for f in flows:
    if f.get('id') not in edges:
        errors.append(f'Missing BPMNEdge for flow {f.get(\"id\")}')

# 7. SUPERFLUOUS_GATEWAY: exactly 1 in AND 1 out
for e in proc.iter():
    tag = e.tag.split('}')[1] if '}' in e.tag else e.tag
    if 'Gateway' in tag:
        inc = len(e.findall('{%s}incoming' % bpmn))
        out = len(e.findall('{%s}outgoing' % bpmn))
        if inc == 1 and out == 1:
            errors.append(f'SUPERFLUOUS_GATEWAY: {tag} {e.get(\"id\")} has exactly 1 in and 1 out')

if errors:
    for e in errors: print('ERROR:', e)
else:
    print('STRUCTURAL CHECK PASSED')
"

python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-gateway-sequence-flows/InvoiceTriageBpmn/InvoiceTriageBpmn.bpmn')
root = tree.getroot()
bpmn = 'http://www.omg.org/spec/BPMN/20100524/MODEL'
bpmndi = 'http://www.omg.org/spec/BPMN/20100524/DI'
ns = {'bpmn': bpmn, 'bpmndi': bpmndi}
proc = root.find('bpmn:process', ns)
errors = []
all_ids = {e.get('id') for e in root.iter() if e.get('id')}

# 1. sequence flow refs resolve
flows = proc.findall('bpmn:sequenceFlow', ns)
for f in flows:
    for attr in ('sourceRef','targetRef'):
        v = f.get(attr)
        if v not in all_ids:
            errors.append(f'SeqFlow {f.get(\"id\")} {attr}={v} not found')

# 2. XOR split (>1 outgoing): must have default + condition on non-default
for gw in proc.findall('bpmn:exclusiveGateway', ns):
    outgoing = [o.text.strip() for o in gw.findall('bpmn:outgoing', ns)]
    if len(outgoing) <= 1:
        continue
    default = gw.get('default')
    if not default:
        errors.append(f'XOR {gw.get(\"id\")} missing default attribute')
    for fid in outgoing:
        if fid == default:
            continue
        f = proc.find(f'bpmn:sequenceFlow[@id=\"{fid}\"]', ns)
        if f is None or f.find('bpmn:conditionExpression', ns) is None:
            errors.append(f'Flow {fid} from XOR {gw.get(\"id\")} missing conditionExpression')

# 3. FAKE_JOIN: tasks and events (NOT gateways) must not have >1 incoming
activity_tags = {'task','scriptTask','serviceTask','userTask','businessRuleTask','sendTask','receiveTask'}
event_tags = {'startEvent','endEvent','intermediateCatchEvent','intermediateThrowEvent'}
for e in proc.iter():
    tag = e.tag.split('}')[1] if '}' in e.tag else e.tag
    if tag in activity_tags | event_tags:
        inc = len(e.findall('{%s}incoming' % bpmn))
        if inc > 1:
            errors.append(f'FAKE_JOIN: {tag} {e.get(\"id\")} has {inc} incoming (use a gateway join)')

# 4. SUPERFLUOUS_GATEWAY: 1 in and 1 out
for e in proc.iter():
    tag = e.tag.split('}')[1] if '}' in e.tag else e.tag
    if 'Gateway' in tag:
        inc = len(e.findall('{%s}incoming' % bpmn))
        out = len(e.findall('{%s}outgoing' % bpmn))
        if inc == 1 and out == 1:
            errors.append(f'SUPERFLUOUS_GATEWAY: {tag} {e.get(\"id\")}')

# 5. Parallel gateways: no conditions
for gw in proc.findall('bpmn:parallelGateway', ns):
    for fid in [o.text.strip() for o in gw.findall('bpmn:outgoing', ns)]:
        f = proc.find(f'bpmn:sequenceFlow[@id=\"{fid}\"]', ns)
        if f is not None and f.find('bpmn:conditionExpression', ns) is not None:
            errors.append(f'Parallel GW {gw.get(\"id\")} flow {fid} has unexpected condition')

# 6. Every node has a BPMNShape; every flow has a BPMNEdge
diag = root.find('bpmndi:BPMNDiagram', ns)
plane = diag.find('bpmndi:BPMNPlane', ns)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', ns)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', ns)}
node_tags = activity_tags | event_tags | {'exclusiveGateway','parallelGateway','inclusiveGateway','eventBasedGateway'}
for e in proc.iter():
    tag = e.tag.split('}')[1] if '}' in e.tag else e.tag
    eid = e.get('id')
    if tag in node_tags and eid:
        if eid not in shapes:
            errors.append(f'Missing BPMNShape for {eid}')
for f in flows:
    if f.get('id') not in edges:
        errors.append(f'Missing BPMNEdge for flow {f.get(\"id\")}')

if errors:
    for e in errors: print('ERROR:', e)
else:
    print('STRUCTURAL CHECK PASSED')
"
